  if (sty==='engraving') return { g:[40,17,56], gg:[38,20,47], house:[32,26,22], bev:[40,12,78], face:[32,28,13], digit:[36,30,90], idx:[8,60,44], line:[30,36,18], anno:[30,32,84], rail:[34,28,38], grain:30, add:false };
