  return { g:[42,32,40], gg:[40,36,31], house:[35,46,15], bev:[46,26,74], face:[34,44,10], digit:[45,20,93], idx:[8,72,66], line:[40,24,58], anno:[44,28,82], rail:[40,30,50], grain:30, add:false };
}
const C = pal();
const sc=(c,a)=>stroke(c[0],c[1],c[2],a*AL);
