const dt = cl(K.t-S.pt,0,.1); S.pt=K.t;
const secN = K.section|0;
let base = .5 + .9*fr(secN*2.71+5);
S.rate = (S.rate==null? base : S.rate + (base-S.rate)*cl(dt*.6,0,1));
const wob = 1 + .2*Math.sin(K.t*.117)+.12*Math.sin(K.t*.31+1.3);
S.th = (S.th||0) + dt*S.rate*wob*P.speed*(.6+2.2*NRG);
const th = S.th;
S.bs = (S.bs||0)*.85 + (A.bass||0)*.15;
const glow = (.5+.5*NRG)*(.55+.5*K.intensity)+S.bs*.25;

// incommensurate plate drift (motion floor w/o audio)
const drx = .9*Math.sin(K.t*.139)+.5*Math.sin(K.t*.291+1.7)+.3*Math.sin(K.t*.463);
const dry = .8*Math.sin(K.t*.107+2.1)+.44*Math.sin(K.t*.253+.6)+.27*Math.sin(K.t*.611+1.9);

