const regH = Math.min(height*.86, u*.92*foot);
const cx0 = cl(P.x,.16,.84)*width + u*.02*NRG*drx;
const cy0 = cl(P.y,.16,.84)*height + u*.018*NRG*dry;
const colW = regW/NC;
const rowH = regH/ND;
const dw = colW*.72, dh = rowH*.86;
const left = cx0 - regW/2, top = cy0 - regH/2;

// per-column irrational difference rate + phase offset (seed)
S.rk = S.rk || {};
const rkey = sd+'|'+NC;
if (S.rk.key!==rkey){ S.rk.key=rkey; S.rk.rt=[]; S.rk.of=[];
  for (let c=0;c<NC;c++){ S.rk.rt[c]= (0.35 + 1.9*fr(c*3.17+1.1))*(1 + 0.13*c); S.rk.of[c]= fr(c*7.7+2.3)*9.9; } }

// ---- grain buffer (toned ground texture) ----
const gk = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gk!==gk){ if (S.gr&&S.gr.remove) S.gr.remove();
  const gw=Math.max(360,Math.min(560,Math.round(width/3))); const gh=Math.max(120,Math.round(gw*height/Math.max(1,width)));
  const g=createGraphics(gw,gh); g.loadPixels();
  for (let y=0;y<gh;y++)for(let x=0;x<gw;x++){ const a=fr(Math.floor(x/7)*13.7+Math.floor(y/7)*7.3+3.1); const b=fr(x*1.13+y*3.31+1.7);
    const v=cl(255*(.5+.34*a+.16*b),0,255); const j=(y*gw+x)*4; g.pixels[j]=v;g.pixels[j+1]=v;g.pixels[j+2]=v;g.pixels[j+3]=255; }
  g.updatePixels(); S.gr=g; S.gk=gk;
}

// ---- ground ----
noStroke(); fill(C.g[0],C.g[1],C.g[2],100); rect(0,0,width,height);
push(); blendMode(MULTIPLY); tint(0,0,100,C.grain); image(S.gr,0,0,width,height); pop(); blendMode(BLEND); noTint();
// big soft inspection wash (screen) — broad motion floor
const wx=width*(.5+.28*Math.sin(K.t*.071)+.12*Math.sin(K.t*.19+2.1));
const wy=height*(.5+.24*Math.sin(K.t*.093+1.1)+.1*Math.sin(K.t*.24+.4));
push(); blendMode(SCREEN); noStroke();
for(let i=5;i>=1;i--){ fc([C.bev[0],C.bev[1]*.5,C.bev[2]],(1.8+1.9*glow)); ellipse(wx,wy,u*(.4+i*.22)*2,u*(.4+i*.22)*1.6); }
pop(); blendMode(BLEND);

// column back-frames (brass rails / stanchions)
for (let c=0;c<=NC;c++){ const x=left+c*colW; noStroke(); fc(C.rail,C.add?14:70);
  rect(x-colW*.055, top-rowH*.28, colW*.11, regH+rowH*.56, colW*.03);
  sc(C.line,58); strokeWeight(Math.max(.5,u*.0011)); noFill(); rect(x-colW*.055, top-rowH*.28, colW*.11, regH+rowH*.56, colW*.03);
}
// top & bottom tie-plates
noStroke(); fc(C.rail,C.add?16:74); rect(left-colW*.09, top-rowH*.36, regW+colW*.18, rowH*.24, rowH*.06); rect(left-colW*.09, top+regH+rowH*.12, regW+colW*.18, rowH*.24, rowH*.06);

// ---- carry linkages (dash-dot diagonal, tens->units path) ----
function dashd(x0,y0,x1,y1,w){ const L=Math.hypot(x1-x0,y1-y0); if(L<1)return; const ux=(x1-x0)/L,uy=(y1-y0)/L,per=w*9;
  sc(C.idx,34+26*anno); strokeWeight(Math.max(.5,w*.4));
  for(let s=0;s<L;s+=per){ const a=s,b=Math.min(L,s+per*.6); line(x0+ux*a,y0+uy*a,x0+ux*b,y0+uy*b); const cc=Math.min(L,s+per*.78),d=Math.min(L,s+per*.86); line(x0+ux*cc,y0+uy*cc,x0+ux*d,y0+uy*d);} }

// ---- odometer register ----
textFont('monospace');
let shapes=0;
for (let c=0;c<NC;c++){
  const val0 = S.rk.of[c] + S.rk.rt[c]*th*(.5+.5*NRG);
  const cxs = left + c*colW + colW/2;
  for (let d=0;d<ND;d++){
    const place = ND-1-d;                       // top drum = highest place
    const v = (val0/Math.pow(10,place));         // odometer: higher place moves 10x slower
    const y = top + d*rowH + rowH/2;
    const x = cxs;
    // housing
    noStroke(); fc(C.house,C.add?20:92); rect(x-dw/2,y-dh/2,dw,dh,dh*.16);
    // face inset (dark drum window)
    fc(C.face,C.add?24:96); rect(x-dw*.4,y-dh*.42,dw*.8,dh*.84,dh*.1);
    // scrolling digits (masked by covering top/bottom with housing gradient bars)
    const dsz=dh*.6;
    push();
    const p=((v%10)+10)%10; const bv=Math.floor(p), fF=p-bv; const off=fF*dsz*1.16;
    textSize(dsz); textAlign(CENTER,CENTER);
    for(let k=-1;k<=1;k++){ const dd=((bv+k)%10+10)%10; const yy=y - k*dsz*1.16 + off; const fade=1-Math.min(1,Math.abs((k*dsz*1.16-off)/(dh*.55)));
      fc(C.digit,(C.add?66:96)*Math.max(0,fade*fade)); text(dd,x,yy); }
    pop();
    // cylinder shading: darken top & bottom of face
    push(); blendMode(sty==='schematic'?BLEND:MULTIPLY); noStroke();
    for(let s=0;s<3;s++){ const a=(sty==='schematic')?0:(26-8*s); fc([0,0,10],a); rect(x-dw*.4,y-dh*.42+s*dh*.06,dw*.8,dh*.07); rect(x-dw*.4,y+dh*.42-(s+1)*dh*.07,dw*.8,dh*.07); }
