    if (P.carry>.15 && d>0 && c<NC){ const yprev=top+(d-1)*rowH+rowH/2; if (d%1===0 && place<ND) dashd(x-dw*.3,y-dh*.5, x-dw*.3, yprev+dh*.5, u*.0016); }
  }
  // column head label
  if (anno>.1){ noStroke(); fc(C.anno,60+28*anno); textSize(Math.max(7,u*.011)); textAlign(CENTER,BOTTOM);
    text('COL '+(NC-c), cxs, top-rowH*.42); }
}

// ---- drive crank on the right side (honest continuous rotation) ----
const gx=Math.min(width-u*.06, left+regW+colW*.55), gy=cy0;
const gr=Math.min(colW*.6,u*.09);
