sc(C.line,C.add?60:82); noFill(); strokeWeight(Math.max(.7,u*.0016)); ellipse(gx,gy,gr*2,gr*2);
const nt=14; sc(C.bev,C.add?50:66); strokeWeight(Math.max(.5,u*.0012));
for(let i=0;i<nt;i++){ const a=th*.5*(.5+.5*NRG)+i*T2/nt; line(gx+Math.cos(a)*gr*.86,gy+Math.sin(a)*gr*.86, gx+Math.cos(a)*gr,gy+Math.sin(a)*gr); }
// crank handle
const ca=th*.5*(.5+.5*NRG); const hx=gx+Math.cos(ca)*gr*.6, hy=gy+Math.sin(ca)*gr*.6;
sc(C.idx,C.add?80:78); strokeWeight(Math.max(1.2,u*.004)); line(gx,gy,hx,hy);
noStroke(); fc(C.idx,C.add?70:88); ellipse(hx,hy,gr*.24,gr*.24);
fc(C.face,C.add?24:90); ellipse(gx,gy,gr*.5,gr*.5); noFill(); sc(C.line,70); ellipse(gx,gy,gr*.5,gr*.5);
if (anno>.3) dashd(gx-gr,gy, left+regW+colW*.1, gy, u*.002);

// ---- plate border + title block ----
const mgn=u*.03; noFill(); sc(C.line,50+20*anno); strokeWeight(Math.max(.8,u*.0022)); rect(mgn,mgn,width-mgn*2,height-mgn*2);
sc(C.line,28+16*anno); strokeWeight(Math.max(.5,u*.001)); rect(mgn*1.6,mgn*1.6,width-mgn*3.2,height-mgn*3.2);
if (anno>.08){ textAlign(RIGHT,CENTER); const bx=width-mgn*1.9,by=height-mgn*1.9;
  noStroke(); fc(C.house,C.add?28:82); rect(bx-u*.31,by-u*.078,u*.31,u*.078);
  noFill(); sc(C.line,64); strokeWeight(Math.max(.5,u*.0012)); rect(bx-u*.31,by-u*.078,u*.31,u*.078);
  line(bx-u*.31,by-u*.05,bx,by-u*.05); line(bx-u*.31,by-u*.025,bx,by-u*.025);
  noStroke(); fc(C.anno,90); textSize(Math.max(7,u*.013));
  text('DIFFERENCE ENGINE No.'+((sd%7)+1), bx-u*.012,by-u*.062);
  text(NC+' COLS x '+ND+' FIGURE WHEELS', bx-u*.012,by-u*.037);
  // running total across the top row of each column
  let tot=''; for(let c=0;c<NC;c++){ const val0=S.rk.of[c]+S.rk.rt[c]*th*(.5+.5*NRG); tot+= (Math.floor(val0/Math.pow(10,ND-1))%10); }
  text('REGISTER '+tot+'   SEED '+sd, bx-u*.012,by-u*.012);
  textAlign(LEFT,CENTER); fc(C.anno,70); text('n '+(S.rate*60).toFixed(1)+' rev/min', mgn*2.1, mgn*2.4);
}
